     1	// Data loaders share the application's real read services and request identity.
     2	// Never turn a failed query into an empty successful snapshot.
     3	async function readPageData(request, location, load) {
     4	  if (typeof location !== 'string' || !location.startsWith('/') || location.startsWith('//') || /[\\\r\n#]/.test(location)) {
     5	    throw new Error('Page location must be an absolute local path with optional query');
     6	  }
     7	  const url = new URL(location, 'http://local.invalid');
     8	  const result = await load({request, pathname:url.pathname, search:url.search});
     9	  if (!result || typeof result.scope !== 'string' || !result.scope || !result.resources ||
    10	      typeof result.resources !== 'object' || Array.isArray(result.resources)) {
    11	    throw new Error('Page loader must return scope and a resources object');
    12	  }
    13	  // Enforce JSON data at the boundary; this also rejects cycles/BigInt.
    14	  return JSON.parse(JSON.stringify({version:1, location, scope:result.scope, resources:result.resources}));
    15	}
    16	
    17	function renderPageHtml(html, data) {
    18	  const json=JSON.stringify(data).replace(/[<>&\u2028\u2029]/g, character =>
    19	    `\\u${character.charCodeAt(0).toString(16).padStart(4,'0')}`);
    20	  const script=`<script id="page-data" type="application/json">${json}</script>`;
    21	  // Before any app module or inline code reads initial data.
    22	  return /<head\b[^>]*>/i.test(html) ? html.replace(/<head\b[^>]*>/i, head=>head+script) : script+html;
    23	}
    24	
    25	module.exports={readPageData,renderPageHtml};
